'use strict';
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s)),E=escapeHTML,F=fmt,T=hhmm;
const S={data:null,schemas:null,token:null,result:null,index:144,route:'twin',config:{stage:'COD',head_case:'Normal',boundary:'TPS',strategy:'follow'},original:null,twin:null,selected:'station',playing:false,speed:1,scenario:null,analytics:null,comparisons:null,importState:null,imports:{},actions:[]};
const SYS={
 'Main pumping':['→','pumps','Six identical pump / motor / VFD trains. Shared hydraulic resistance.'],
 'HVAC':['❄','hvac','Six illustrative zones with weather-linked electrical demand.'],
 'Ventilation':['≋','ventilation','Safety ventilation and screen-room extraction.'],
 'Odour control':['◌','odour','TPS OCU extraction fans, scrubber circulation and dosing.'],
 'Regional odour':['◎','regional','Regional odour control facilities (ROCF), within the optional network boundary.'],
 'Central cooling':['⌘','cooling','Chillers, circulation and heat rejection.'],
 'Water services':['◇','water','RW polishing and service-water auxiliaries.'],
 'Auxiliary pumping':['↝','aux','Self-cleaning and drainage duty schedules.'],
 'Controls and ICT':['⌁','controls','PLC, SCADA, field instruments, CCTV and communication.'],
 'Buildings and lighting':['☷','buildings','Internal and external lighting schedules.'],
 'Electrical losses':['ϟ','electrical','Upstream transformer, UPS and distribution losses.']};
const NAV=[['twin','◈','Digital twin'],['performance','⌁','Energy performance'],['systems','▦','Systems & assets'],['hydraulics','≋','Hydraulics & storage'],['analytics','⌕','Deviation analytics'],['scenarios','⤴','Scenario lab'],['data','↑','Data studio'],['reports','▤','Reports & evidence']];
function navIcon(id){let paths={twin:'M12 3l9 5v8l-9 5-9-5V8z M3 8l9 5 9-5 M12 13v8',performance:'M3 18l5-7 4 4 7-11 M3 21h18',systems:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',hydraulics:'M2 8c4-5 6 5 10 0s6 5 10 0 M2 15c4-5 6 5 10 0s6 5 10 0',analytics:'M10 3a7 7 0 1 0 0 14a7 7 0 1 0 0-14 M15 15l6 6',scenarios:'M5 20V4 M5 12h7l6-7 M13 5h5v5 M5 12h7l6 7',data:'M4 15v5h16v-5 M12 16V3 M7 8l5-5 5 5',reports:'M5 3h11l3 3v15H5z M8 9h8 M8 13h8 M8 17h5'};return `<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.systems}"/></svg>`}
const COLORS=Chart.colors;
function toast(t){let el=$('#toast');el.textContent=t;el.style.display='block';clearTimeout(S.toast);S.toast=setTimeout(()=>el.style.display='none',5500)}
async function api(path,payload){let r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-Session-Token':S.token},body:JSON.stringify(payload)});let j=await r.json();if(!r.ok||j.error)throw Error(j.error||'Request failed');return j}
async function busy(fn){$('#busy').hidden=false;try{return await fn()}catch(e){toast(e.message);console.error(e)}finally{$('#busy').hidden=true}}
function route(s){location.hash=s}
function current(){return S.result.rows[Math.min(S.index,S.result.rows.length-1)]}
function tip(s){return `<button class="info" type="button" data-tip="${E(s)}" aria-label="${E(s)}">i</button>`}
function head(eyebrow,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtext">${desc}</p></div><div class="actions">${actions}</div></div>`}
function panel(title,sub,body,actions=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2><small>${sub}</small></div>${actions}</div>${body}</section>`}
function kpi(label,value,unit,foot,help){return `<div class="kpi"><div class="label">${label}${help?tip(help):''}</div><div class="value">${value}<small>${unit}</small></div><div class="foot">${foot}</div></div>`}
function overviewKPIs(){let r=S.result;return '<div class="kpis">'+kpi('Station energy',F(r.energy_kwh/1000,1),'MWh / day','Integrated across '+r.rows.length+' intervals','Sum of electrical power × interval duration. Includes auxiliaries within the selected boundary.')+kpi('Delivered water',F(r.volume_m3/1000,1),'× 1,000 m³','Storage balance explicitly tracked','Sum of total station discharge. Parallel pump flows are counted once.')+kpi('Specific energy',F(r.sec,3),'kWh / m³','Main pumps '+F(r.main_sec,3)+' kWh/m³','Whole-station electricity / delivered volume. Compare like-for-like head, flow and system boundary.')+kpi('Electricity cost',F(r.cost_aed/1000,2),'k AED / day','Illustrative tariff · '+F(r.co2_kg/1000,1)+' t CO₂e','Interval energy × tariff. Carbon is a user-entered factor, not a verified project inventory.')+'</div>'}
function table(headers,rows){return '<div class="table-wrap"><table><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function alert(text,kind='neutral'){return `<div class="alert ${kind}"><span>ⓘ</span><span>${text}</span></div>`}
function chart(id){return `<div id="${id}" class="chart"></div>`}
function curveSeries(key,name,color,transform){return {name,color,data:S.result.rows.map(r=>[r.minute,transform?transform(r):r[key]])}}
function insight(n,title,text,link){return `<div class="insight"><span class="badge-number">${n}</span><div><h3>${title}</h3><p>${text}</p>${link?`<a class="text-btn" style="color:var(--teal)" href="#${link}">Explore analysis →</a>`:''}</div></div>`}
function sysRoute(name){return name==='Main pumping'?'hydraulics':'systems/'+encodeURIComponent(name)}
function systemFromId(id){return ({pumps:'Main pumping',wet:'Main pumping',odour:'Odour control',cooling:'Central cooling',water:'Water services'})[id]||((id||'').startsWith('Z-')?'HVAC':null)}
function meta(id){let r=current(),p=id.startsWith('P-'),zone=S.data.zones.find(z=>z.zone_id===id),asset=S.data.loads.find(a=>a.asset_id===id),sys=systemFromId(id);if(id==='station')return {name:'Terminal pumping station',tag:'Whole-station view',system:'Station',kw:r.total_kw,energy:S.result.energy_kwh,level:r.level_end_m,path:'performance',desc:'Follow the water, power and operating context across the station.'};if(id==='wet')return {name:'Inlet and wet well',tag:'Wet-well storage',system:'Main pumping',kw:r.main_kw,energy:S.result.systems['Main pumping'],level:r.level_end_m,path:'hydraulics',kwLabel:'Linked pump demand',energyLabel:'Linked pump energy',desc:'The stored water is not an electrical load. Energy figures here refer to the connected main pumping system.'};if(p){let i=+id.slice(2)-1;return {name:'Main pump '+id,tag:'Pump / motor / VFD',system:'Main pumping',kw:r.active_ids.includes(id)?r.main_kw/r.pumps_running:0,energy:S.result.rows.reduce((s,x)=>s+(x.active_ids.includes(id)?x.main_kw/x.pumps_running*x.duration_h:0),0),running:r.active_ids.includes(id),path:'assets/'+id,desc:'Selected train. Identical curves and common-speed allocation are assumed.',runtime:S.result.pump_hours[i]}}
 if(zone)return {name:zone.name,tag:id+' · '+zone.level,system:'HVAC',kw:r.zones[id]||0,energy:S.result.zones[id]||0,temp:r.zone_temps[id],path:'systems/HVAC/'+id,desc:'Inspect weather-linked demand, illustrative room signals and associated equipment.'};
 if(asset)return {name:asset.name,tag:id,system:asset.system,kw:r.assets[id]||0,energy:S.result.assets[id]||0,path:'assets/'+id,desc:'Assumed electrical load with an explicit operating schedule.'};
 return {name:id==='wet'?'Inlet and wet well':sys||id,tag:id==='wet'?'Wet-well storage':'System energy boundary',system:sys,kw:r.systems[sys]||0,energy:S.result.systems[sys]||0,level:r.level_end_m,path:sysRoute(sys),desc:SYS[sys]?.[2]||'Select a highlighted system to explore.'}}
function renderInspector(){let el=$('#inspector');if(!el)return;let m=meta(S.selected);el.innerHTML=`<div><div class="eyebrow">Asset inspector</div><span class="pill green">${E(m.tag)}</span></div><div><h2>${E(m.name)}</h2><p class="subtext">${m.desc}</p></div><div class="metric-pair"><div class="metric-mini"><small>${m.kwLabel||"At "+T(current().minute)}</small><strong>${F(m.kw)}<small> kW</small></strong></div><div class="metric-mini"><small>${m.energyLabel||"Daily energy"}</small><strong>${F(m.energy/1000,2)}<small> MWh</small></strong></div></div><dl class="kv"><dt>Source</dt><dd>Model estimate</dd><dt>${m.temp!=null?'Room signal':m.runtime!=null?'Runtime':'Wet-well level'}</dt><dd>${m.temp!=null?F(m.temp,1)+' °C':m.runtime!=null?F(m.runtime,1)+' h':F(current().level_end_m,2)+' m'}</dd><dt>Current duty</dt><dd>${current().pumps_running} / 6 pumps</dd><dt>Head case</dt><dd>${E(S.config.head_case)}</dd></dl><div class="divider"></div><p class="scoped-note">Schematic geometry. The original drawing informs the deep-shaft arrangement; external buildings and HVAC zones are illustrative.</p><button class="button primary" data-route="${m.path}">Open detailed analysis →</button>`}
function renderTwin(){let r=S.result;$('#content').innerHTML=head('Spatial intelligence','See the station. Understand the energy.','Explore connected systems, then follow the evidence down to each zone and asset.',`<button class="button ghost" data-action="tour">Guided walkthrough →</button>`)+overviewKPIs()+`<div class="scene-layout"><div class="scene"><canvas id="twinCanvas" aria-label="Interactive 3D station. Drag to orbit, scroll to zoom. Use the asset selector below for keyboard access."></canvas><div class="scene-tools"><button class="button small" data-view="site">Site</button><button class="button small active" data-view="cutaway">Cutaway</button><button class="button small" data-view="plan">Plan</button><button class="button small" data-action="energyLayer" title="Colour operating equipment by energy state">Energy layer</button><button class="button small" data-action="resetView" aria-label="Reset camera">⟲</button></div><div class="scene-corner">TPS / CONNECTED MODEL<span>6 pumps · ${S.data.zones.length} HVAC zones · ${S.data.loads.length} load groups</span></div><div class="scene-caption"><b>Drag to orbit · Scroll to zoom · Click to inspect</b>Conceptual 3D · Depth compressed for readability · Not an as-built model</div><div class="scene-key"><span><i style="background:#58e1b4"></i>Pumping</span><span><i style="background:#6dbaff"></i>Cooling</span><span><i style="background:#bdabff"></i>Odour</span></div></div><aside class="inspector" id="inspector"></aside></div><div class="actions" style="margin:-8px 0 20px"><label class="field" style="flex-direction:row;align-items:center">Inspect asset <select id="assetSelect"><option value="station">Whole station</option>${['pumps','wet','cooling','odour',...S.data.zones.map(z=>z.zone_id),...Array.from({length:6},(_,i)=>'P-0'+(i+1))].map(id=>`<option value="${id}">${E(meta(id).name)}</option>`).join('')}</select></label><small>Clicking a model object updates the inspector; open its detail page for deeper analysis.</small></div><div class="grid2">${panel('The daily operating picture','Electrical demand across one representative day',chart('overviewTrend')+Chart.legend([{name:'Whole station'},{name:'Main pumping'},{name:'Auxiliaries'}]))}${panel('What deserves attention','Findings calculated from the current scenario',insight('01','Hydraulic service',r.overflow_m3>1?F(r.overflow_m3)+' m³ exceeded the assumed wet-well storage limit. Review capacity.':'No modeled spill within the selected storage envelope. Final level '+F(r.final_level_m,2)+' m.','hydraulics')+insight('02','Auxiliary contribution',F(100*(r.energy_kwh-r.systems['Main pumping'])/r.energy_kwh,1)+'% of total electrical energy comes from auxiliary systems.','systems')+insight('03','A data-analysis story','Open the seeded meter series: detect an injected excess-load event using a held-out regression baseline.','analytics'))}</div>`;
 S.twin=new Twin3D($('#twinCanvas'),{value:id=>meta(id),onSelect:id=>{S.selected=id;$('#assetSelect').value=id;renderInspector()},onHover:(id,e)=>{let m=meta(id);showTip(`<strong>${E(m.name)}</strong>${m.kwLabel?E(m.kwLabel)+": ":""}${F(m.kw)} kW · ${T(current().minute)}<br><small>Click to select and open its analysis</small>`,e.clientX,e.clientY)}});renderInspector();Chart.line('overviewTrend',[curveSeries('total_kw','Whole station',COLORS[0]),curveSeries('main_kw','Main pumping',COLORS[1]),curveSeries('aux_kw','Auxiliaries',COLORS[2])],{time:true,unit:'kW'});$('#assetSelect').onchange=e=>{S.selected=e.target.value;S.twin.selected=S.selected;S.twin.draw();renderInspector()};
}
function heatmap(){let rows=S.result.rows;let html='<div class="heat-scroll"><div class="heatmap"><div></div>'+Array.from({length:24},(_,h)=>`<span class="hour">${h.toString().padStart(2,'0')}</span>`).join('');let max=Math.max(...rows.map(r=>r.total_kw));for(let s of Object.keys(SYS)){let vals=Array.from({length:24},(_,h)=>{let rr=rows.filter(r=>Math.floor(r.minute/60)===h);return rr.reduce((a,r)=>a+r.systems[s]*r.duration_h,0)});let localMax=Math.max(...vals,1);html+=`<a class="row-name" href="#${sysRoute(s)}">${E(s)}</a>`+vals.map((v,h)=>`<div class="cell" data-route="${sysRoute(s)}" style="background:rgba(88,225,180,${.09+.8*v/localMax})" data-tip="${E(s)} · ${T(h*60)} · ${F(v,1)} kWh. Row-normalized intensity."></div>`).join('')}return html+'</div></div>'}
function renderPerformance(){let r=S.result;$('#content').innerHTML=head('Energy performance','Every kilowatt has a place.','Compare demand, cost, unit energy and auxiliary contributions within a consistent boundary.',`<button class="button" data-action="exportIntervals">↓ Export intervals</button>`)+overviewKPIs()+`<div class="grid2">${panel('Demand profile','Power is integrated using each interval duration',chart('energyTrend')+Chart.legend([{name:'Total electrical demand'},{name:'Main pumping'},{name:'Auxiliary demand'}])+`<div class="inline-metrics"><div class="metric-mini"><small>Mean demand</small><strong>${F(r.energy_kwh/24)} kW</strong></div><div class="metric-mini"><small>Peak demand</small><strong>${F(r.peak_kw)} kW</strong></div><div class="metric-mini"><small>Load factor</small><strong>${F(r.energy_kwh/24/r.peak_kw*100,1)}%</strong></div></div><p class="scoped-note">Hover over the chart for interval values. The green cursor follows the bottom playback bar. Composition is an energy balance across the selected station boundary.</p>`)}${panel('Energy composition','Select a system to drill into its load groups','<div id="energyBars"></div>')}</div>`+panel('When energy is used','Hourly kWh · Each row is normalized separately to reveal its daily schedule',heatmap())+`<div class="grid-even">${panel('Flow versus electrical demand','Operating context explains part of the load variation',chart('flowPower'))}${panel('Flow versus specific energy','Whole-station and main-pump boundaries shown separately',chart('flowSEC')+Chart.legend([{name:'Whole station'},{name:'Main pumping'}]))}</div><div class="grid-even">${panel('Electricity cost by hour','Illustrative time-of-use profile, not a utility tariff','<div id="hourCost"></div>')}${panel('Load duration curve','Demand sorted from highest to lowest; no chronological information',chart('duration')+`<p class="plot-note">Load factor: ${F(r.energy_kwh/24/r.peak_kw*100,1)}% · Peak apparent power: ${F(r.peak_kw/(S.config.pf||.96))} kVA. Power factor does not directly reduce kWh.</p>`)}</div>`;
 Chart.line('energyTrend',[curveSeries('total_kw','Total electrical demand',COLORS[0]),curveSeries('main_kw','Main pumping',COLORS[1]),curveSeries('aux_kw','Auxiliary demand',COLORS[2])],{time:true,unit:'kW'});Chart.bars('energyBars',Object.entries(r.systems).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]).map(([label,value])=>({label,value:value/1000})),{unit:'MWh',decimals:1,percent:true,click:x=>route(sysRoute(x.label))});Chart.line('flowPower',[{name:'Station demand',data:r.rows.map(x=>[x.outflow_m3s,x.total_kw]),scatter:true}],{unit:'kW',xlabel:'Flow m³/s'});Chart.line('flowSEC',[{name:'Whole station',data:r.rows.filter(x=>x.water_m3>0).map(x=>[x.outflow_m3s,x.energy_kwh/x.water_m3]),scatter:true},{name:'Main pumps',data:r.rows.filter(x=>x.water_m3>0).map(x=>[x.outflow_m3s,x.main_kw*x.duration_h/x.water_m3]),scatter:true}],{unit:'kWh/m³',xlabel:'Flow m³/s',decimals:3});let hrs=Array.from({length:24},(_,h)=>({label:T(h*60),value:r.rows.filter(x=>Math.floor(x.minute/60)===h).reduce((a,x)=>a+x.cost_aed,0)}));Chart.bars('hourCost',hrs.filter((x,i)=>i%3===0).map((x,i)=>({label:x.label+'–'+T((i*3+3)*60),value:hrs.slice(i*3,i*3+3).reduce((a,x)=>a+x.value,0)})),{unit:'AED'});let sorted=[...r.rows].sort((a,b)=>b.total_kw-a.total_kw),elapsed=0;Chart.line('duration',[{name:'Demand',data:sorted.map(x=>{let p=[elapsed,x.total_kw];elapsed+=x.duration_h;return p}),fill:true}],{unit:'kW',xlabel:'Cumulative hours'});
}
function renderSystems(parts){if(parts[1])return renderSystem(decodeURIComponent(parts[1]),parts[2]);$('#content').innerHTML=head('System hierarchy','From station to system to asset.','Open a system to examine its energy demand, operating assumptions and component-level evidence.')+`<div class="grid3">${Object.entries(SYS).map(([name,[icon,id,desc]])=>`<a class="system-card" href="#${sysRoute(name)}"><div class="sicon">${icon}<span style="font-size:14px">→</span></div><h3>${name}</h3><p>${desc}</p><div class="sval">${F(S.result.systems[name]/1000,2)} <small>MWh / day</small></div><div class="progress"><i style="width:${100*S.result.systems[name]/S.result.energy_kwh}%"></i></div><footer><span>${name==='Main pumping'?'6 pump trains':S.data.loads.filter(a=>a.system===name).length+' load groups'}</span><span>${F(100*S.result.systems[name]/S.result.energy_kwh,1)}% of station</span></footer></a>`).join('')}</div>`}
function renderSystem(name,zoneId){if(!SYS[name]){route('systems');return}if(name==='Main pumping'){route('hydraulics');return}let zone=zoneId?S.data.zones.find(z=>z.zone_id===zoneId):null,loads=S.data.loads.filter(a=>a.system===name&&(!zone||a.zone_id===zoneId)),energy=zone?S.result.zones[zoneId]:S.result.systems[name],series=S.result.rows.map(r=>[r.minute,zone?(r.zones[zoneId]||0):r.systems[name]]),peak=Math.max(...series.map(x=>x[1]));let extras='';
 if(name==='HVAC'&&!zone)extras=panel('A spatial view of HVAC','Illustrative room grouping · Click a zone for thermal context and associated equipment',`<div class="mini-map">${S.data.zones.map(z=>`<a href="#systems/HVAC/${z.zone_id}" class="zone-tile"><small>${E(z.level)} · ${F(z.area_m2)} m²</small><h3>${E(z.name)}</h3><b>${F(S.result.zones[z.zone_id])} <small>kWh / day</small></b><small>Setpoint ${F(z.setpoint_c)} °C · Explore zone →</small></a>`).join('')}</div>`);
 if(name==='Central cooling')extras=panel('Thermal and electrical balance','Chiller duty = assumed background heat + 75% of modeled motor loss',`<div class="grid3"><div class="metric-mini"><small>Thermal duty at ${T(current().minute)}</small><strong>${F(current().cooling_heat_kw)} kWth</strong></div><div class="metric-mini"><small>Assumed cooling COP</small><strong>${F(S.config.cooling_cop||4.5,2)}</strong></div><div class="metric-mini"><small>Calculated flow at ΔT = ${F(S.config.cooling_delta_k||5,1)} K</small><strong>${F(current().cooling_flow_ls,1)} L/s</strong></div></div><p class="scoped-note">Chiller electricity is thermal duty / COP. Circulation and heat rejection remain separate loads. HVAC zones use a separate illustrative air-cooled system, preventing double counting.</p>`)+panel('Cooling duty through the day','Response to stage and motor losses',chart('thermal'));
 if(name==='Odour control')extras=panel('Air service and electrical demand','Assumed fan resistance and power balance; not a pollutant-removal simulation',`<div class="grid3"><div class="metric-mini"><small>Estimated fan airflow</small><strong>${F(current().odour_airflow_m3h)} m³/h</strong></div><div class="metric-mini"><small>Required minimum assumption</small><strong>${F(S.config.odour_min_air_m3h||150000)} m³/h</strong></div><div class="metric-mini"><small>Assumed system pressure drop</small><strong>${F(S.config.odour_dp_pa||3500)} Pa</strong></div></div><p class="scoped-note">Qair = fan electrical input × assumed total efficiency / pressure drop. Scenario efficiency changes retain the same inferred air duty. ${S.result.odour_shortfall_intervals} intervals fall below the assumed minimum; this screen does not demonstrate H₂S or odour-removal compliance.</p>`);
 if(['Odour control','Regional odour','Ventilation'].includes(name))extras+=alert('Efficiency scenarios change fan input for the same assumed air duty. Minimum OCU airflow is screened separately against the configured assumption. No H₂S removal, pressure or safe-airflow compliance is inferred from this energy model.');
 $('#content').innerHTML=`<a class="route-back" href="#${zone?'systems/HVAC':'systems'}">← ${zone?'HVAC zones':'All systems'}</a>`+head(zone?'Zone intelligence':'System intelligence',E(zone?.name||name),zone?`${E(zone.zone_id)} · ${E(zone.level)} · ${F(zone.area_m2)} m² assumed area. ${SYS[name][2]}`:SYS[name][2],name==='Regional odour'?'':`<button class="button" data-action="showOnTwin" data-id="${zoneId||SYS[name][1]}">Locate in 3D →</button>`)+`<div class="kpis">${kpi('Daily energy',F(energy),'kWh','Selected boundary')}${kpi('Peak demand',F(peak,1),'kW','Profile maximum')}${kpi('Station contribution',F(100*energy/S.result.energy_kwh,1),'%','Share of total electricity')}${kpi(zone?'Thermal setpoint':'Load groups',zone?F(zone.setpoint_c):loads.length,zone?'°C':'groups',zone?'Illustrative; not a safety setting':'Traceable load inventory')}</div>`+extras+`<div class="grid-even">${panel('Electrical demand','Selected system / zone',chart('systemTrend'))}${panel(zone?'Room and outdoor temperature':'Component contribution',zone?'Room temperature is an illustrative signal, not a solved building thermal model':'Daily energy by load group',zone?chart('zoneTemperature'):'<div id="componentBars"></div>')}</div>`+panel('Associated equipment','Click a load group to inspect its schedule and calculation',table(['Asset','Equipment','Rated input','Duty','Load factor','Schedule','Daily kWh'],loads.map(a=>[`<a href="#assets/${E(a.asset_id)}">${E(a.asset_id)} →</a>`,E(a.name),F(a.input_kw)+' kW',E(a.duty_units),F(100*a.load_factor)+'%',E(a.schedule),F(S.result.assets[a.asset_id])])));
 Chart.line('systemTrend',[{name:zone?.name||name,data:series,fill:true}],{time:true,unit:'kW'});if(zone)Chart.line('zoneTemperature',[{name:'Illustrative room',data:S.result.rows.map(r=>[r.minute,r.zone_temps[zoneId]])},curveSeries('outdoor_c','Outdoor',COLORS[1])],{time:true,unit:'°C',ymin:18,bands:[{y:+zone.max_temp_c,label:'Assumed review threshold'}]});else Chart.bars('componentBars',loads.map(a=>({label:a.name,value:S.result.assets[a.asset_id],id:a.asset_id})).sort((a,b)=>b.value-a.value),{click:a=>route('assets/'+a.id)});if(name==='Central cooling')Chart.line('thermal',[curveSeries('cooling_heat_kw','Required thermal duty',COLORS[1])],{time:true,unit:'kWth'});
}
