function renderHydraulics(){let r=S.result,c=r.settings;$('#content').innerHTML=head('Hydraulic context','The flow, the head and the operating envelope.','Common-pipe losses use total station discharge. Identical pumps share flow at a common speed.',`<button class="button" data-action="loadCompare">Compare 4 stages × 3 heads →</button>`)+`<div class="kpis">${kpi('Modeled spill',F(r.overflow_m3),'m³','Volume beyond assumed storage limit','This is a numerical storage overflow, not an infrastructure flood prediction.')}${kpi('Storage change',F(r.storage_change_m3),'m³','End minus beginning of day','Positive values mean water remains stored. This is not delivered volume.')}${kpi('Total starts',r.total_starts,'starts','Minimum on/off constraints tracked')}${kpi('Balance residual',F(r.mass_balance_error_m3,6),'m³','Inflow − discharge − spill − Δstorage')}</div>`+(r.emergency_stops?alert(r.emergency_stops+' low-water protection overrides occurred. Minimum run-time constraints were overridden to protect the simulated low-level bound.','red'):'')+`<div class="grid2">${panel('Inflow and delivered flow','Storage shifts discharge within the allowed water-level band',chart('flowBalance')+Chart.legend([{name:'Inflow'},{name:'Delivered flow'}]))}${panel('Wet-well operating band','Effective area is an independent assumption, not the full shaft area',`<div style="display:flex;gap:25px;align-items:center"><div class="water-tank"><div id="tankWater" class="water"></div><div id="tankLevel" class="level"></div></div><dl class="kv" style="flex:1"><dt>Effective area</dt><dd>${F(c.area_m2)} m²</dd><dt>Minimum / maximum</dt><dd>${F(c.level_min,1)} / ${F(c.level_max,1)} m</dd><dt>Usable storage</dt><dd>${F(c.area_m2*(c.level_max-c.level_min))} m³</dd><dt>Initial / final</dt><dd>${F(c.level_initial,2)} / ${F(r.final_level_m,2)} m</dd><dt>Strategy</dt><dd>${E(c.strategy)}</dd></dl></div>`)}</div><div class="grid-even">${panel('Water level over time','Relative modeled level; not an absolute drawing elevation',chart('levelTrend'))}${panel('Head decomposition','Static lift changes with water level; friction uses total flow',chart('headTrend')+Chart.legend([{name:'Total required head'},{name:'Static component'},{name:'Shared friction'}]))}</div><div class="grid-even">${panel('Single-pump curve and operating points','Approximate expected curve at 94.1% nominal speed; affinity-scaled curves',chart('pumpCurve')+Chart.legend([{name:'Reference 94.1%'},{name:'85% nominal'},{name:'70% nominal'},{name:'Operating points'}]))}${panel('Shared system curves','Q axis is total station flow, not single-pump flow',chart('commonCurve')+Chart.legend([{name:'Low'},{name:'Normal'},{name:'High'}]))}</div>`+panel('Six-train operating record','Energy and runtime follow selected active IDs; minimum run and rest times constrain starts',table(['Train','Runtime','Starts','Allocated electrical energy','Current state'],Array.from({length:6},(_,i)=>{let id='P-0'+(i+1),m=meta(id);return [`<a href="#assets/${id}">${id} →</a>`,F(r.pump_hours[i],2)+' h',r.pump_starts[i],F(m.energy)+' kWh',`<span class="pill ${m.running?'green':''}">${i>=c.available?'Unavailable':m.running?'Running':'Idle'}</span>`]})))+alert('The scheduler is a transparent heuristic, not a certified optimum. Assumed flow bounds and speed limits are enforced; NPSHa, transients, downstream storage and detailed control logic require separate engineering validation.')+'<div id="comparisonArea"></div>';
 Chart.line('flowBalance',[curveSeries('inflow_m3s','Inflow',COLORS[0]),curveSeries('outflow_m3s','Delivered flow',COLORS[1])],{time:true,unit:'m³/s'});Chart.line('levelTrend',[curveSeries('level_end_m','Wet-well level',COLORS[0])],{time:true,unit:'m',ymin:0,ymax:c.level_max+.6,bands:[{y:c.level_min,label:'Minimum'},{y:c.level_max,label:'Maximum'}]});Chart.line('headTrend',[curveSeries('head_m','Total required head',COLORS[0]),curveSeries('static_head_m','Static component',COLORS[1]),curveSeries('friction_m','Shared friction',COLORS[2])],{time:true,unit:'m'});let cv=S.data.curve;Chart.line('pumpCurve',[...[.941,.85,.70].map((speed,i)=>({name:F(speed*100,1)+'% nominal',data:cv.filter(p=>+p.q_m3s>=2.05).map(p=>[p.q_m3s*speed/.941,p.head_m*(speed/.941)**2]),color:COLORS[i]})),{name:'Operating points',data:r.rows.filter(x=>x.pumps_running).map(x=>[x.outflow_m3s/x.pumps_running,x.head_m]),scatter:true,color:COLORS[3]}],{unit:'m',xlabel:'Single-pump flow m³/s'});Chart.line('commonCurve',['Low','Normal','High'].map((name,i)=>({name,color:COLORS[i],data:S.data.system.filter(x=>x.head_case===name).map(x=>[+x.total_flow_m3s,+x.static_head_m + +x.shared_friction_m])})),{unit:'m',xlabel:'Total discharge m³/s'});updateTime();if(S.comparisons)renderComparisons()}
