function renderComparisons(){let el=$('#comparisonArea');if(!el)return;el.innerHTML=panel(S.comparisons.length+' planning cases','Same data and assumptions, varying development stage and static-head scenario',table(['Stage','Head','Energy','Unit energy','Cost','Spill','Starts'],S.comparisons.map(r=>[E(r.settings.stage),E(r.settings.head_case),F(r.energy_kwh/1000,1)+' MWh',F(r.sec,3)+' kWh/m³',F(r.cost_aed)+' AED',F(r.overflow_m3)+' m³',r.total_starts]))) }
async function renderAnalytics(){let r=S.result;$('#content').innerHTML=head('Statistical evidence','Separate operating context from unexplained demand.','A physics baseline and an independent regression offer two views of the same interval data.',`<button class="button" data-route="data">Import meter CSV →</button>`)+alert('Included meter readings are synthetic, with an injected +8% excess load at 14:00–16:00. They correspond to the default COD / Normal / follow case. Use matching data when you change the scenario.')+`<div id="analyticsBody"><div class="loading"><div class="spinner"></div>Fitting the training window and evaluating held-out intervals…</div></div>`;
 if(!S.analytics){try{S.analytics=await api('analytics',{data:S.data,settings:S.config})}catch(e){if($('#analyticsBody'))$('#analyticsBody').innerHTML=alert(E(e.message),'red');return}}if(!$('#analyticsBody'))return;let a=S.analytics;
 if(!a.available){$('#analyticsBody').innerHTML=alert(E(a.reason));return}
 let source=E(a.source);$('#analyticsBody').innerHTML=`<div class="kpis">${kpi('Held-out RMSE',F(a.rmse_kw,1),'kW','Error on the second half only','Regression trained on the first half. This error includes the intentionally injected event.')}${kpi('Held-out R²',F(a.r2,3),'','May be negative under drift','R² can be poor despite a good training fit. It is not evidence of causal energy savings.')}${kpi('Flagged intervals',a.flagged,'intervals','Held-out residual screening','Absolute residual > max(3 × training RMSE, 3% of predicted power). Advisory only.')}${kpi('Positive physics deviation',F(a.positive_physics_deviation_kwh),'kWh','Not verified avoidable energy','Positive observed-minus-modeled energy. May include model error, sensor error or changed operating conditions.')}</div><div class="grid2">${panel('Three perspectives on station demand','Model, imported signal and regression prediction',chart('meterTrend')+Chart.legend([{name:'Imported meter signal'},{name:'Physics baseline'},{name:'Regression baseline'}]))}${panel('How the analysis works','A transparent model you can explain in an interview',insight('01','Align before comparing',a.matched+' intervals matched by time and duration; '+a.unmatched+' unmatched meter rows excluded.')+insight('02','Train without peeking',a.train_rows+' earlier intervals train power = β₀ + β₁ × (QH) + β₂ × outdoor temperature.')+insight('03','Evaluate the future window',a.test_rows+' later intervals are evaluated. Thresholds use training error, not the test event.'))}</div><div class="grid-even">${panel('Regression residuals','Imported minus regression-predicted kW; chronological split is explicit',chart('residualTrend'))}${panel('Observed versus predicted','Held-out values only; the diagonal is perfect agreement',chart('obsPred'))}</div>`+panel('Review queue','Flagged intervals are evidence for investigation, not automatic diagnoses',table(['Time','Signal','Prediction','Residual','Threshold','Recommended review'],a.rows.filter(x=>x.flag).slice(0,40).map(x=>[T(x.minute),F(x.observed)+' kW',F(x.prediction)+' kW',F(x.regression_residual)+' kW',F(x.threshold_kw)+' kW','Check load state, flow/head and meter quality'])))+panel('Baseline record','Keep assumptions and provenance attached to the result',`<dl class="kv"><dt>β₀ / intercept</dt><dd>${F(a.beta[0],4)}</dd><dt>β₁ / Q × H</dt><dd>${F(a.beta[1],4)}</dd><dt>β₂ / outdoor temperature</dt><dd>${F(a.beta[2],4)}</dd><dt>Training interval count</dt><dd>${a.train_rows}</dd><dt>Source class</dt><dd style="max-width:550px;white-space:normal">${source}</dd></dl><p class="scoped-note">Association is not causation. The synthetic dataset is small and autocorrelated. No independently validated savings, fault diagnosis or predictive-maintenance accuracy is claimed.</p><button class="button" style="margin-top:15px" data-action="exportAnalytics">↓ Export residual evidence CSV</button>`);
 Chart.line('meterTrend',[{name:'Imported meter signal',data:a.rows.map(x=>[x.minute,x.observed]),color:COLORS[0]},{name:'Physics baseline',data:a.rows.map(x=>[x.minute,x.physics]),color:COLORS[1]},{name:'Regression baseline',data:a.rows.map(x=>[x.minute,x.prediction]),color:COLORS[2],dash:true}],{time:true,unit:'kW'});Chart.line('residualTrend',[{name:'Training residual',data:a.rows.filter(x=>!x.holdout).map(x=>[x.minute,x.regression_residual]),color:COLORS[1]},{name:'Held-out residual',data:a.rows.filter(x=>x.holdout).map(x=>[x.minute,x.regression_residual]),color:COLORS[0]},{name:'Upper threshold',data:a.rows.map(x=>[x.minute,x.threshold_kw]),color:COLORS[2],dash:true},{name:'Lower threshold',data:a.rows.map(x=>[x.minute,-x.threshold_kw]),color:COLORS[2],dash:true}],{time:true,unit:'kW'});let test=a.rows.filter(x=>x.holdout),min=Math.min(...test.map(x=>Math.min(x.prediction,x.observed))),max=Math.max(...test.map(x=>Math.max(x.prediction,x.observed)));Chart.line('obsPred',[{name:'Held-out signal',data:test.map(x=>[x.prediction,x.observed]),scatter:true},{name:'Perfect agreement',data:[[min,min],[max,max]],dash:true}],{unit:'Observed kW',xlabel:'Predicted kW',ymin:min*.95});
}
function renderScenarios(){let c=S.result.settings;$('#content').innerHTML=head('Decision laboratory','Compare a change. Preserve the service.','Test operating strategy and efficiency assumptions, then check hydraulic service before interpreting cost savings.')+`<div class="grid3"><button class="case-tile" data-preset="efficiency"><h3>01 · Efficiency upgrade</h3><small>Same hydraulic duty; improved conversion efficiency.</small></button><button class="case-tile" data-preset="storage"><h3>02 · Storage smoothing</h3><small>Wet-well feedback with minimum on/off constraints.</small></button><button class="case-tile" data-preset="tariff"><h3>03 · Tariff-aware operation</h3><small>Heuristic load shifting with end-of-day recovery.</small></button></div><div style="height:20px"></div>`+panel('Alternative scenario','These controls change a simulation, never actual equipment',`<div class="form-grid"><label>Operating strategy<select id="altStrategy"><option value="follow">Demand following</option><option value="storage">Storage smoothing</option><option value="tariff">Tariff-aware heuristic</option></select></label><label>Pump efficiency multiplier ${tip('A relative change applied to the approximate pump-efficiency curve; not an OEM guarantee.')}<input id="altPump" type="number" value="1.02" min="0.8" max="1.04" step="0.01"></label><label>Motor efficiency (%)<input id="altMotor" type="number" value="97.5" min="50" max="100" step="0.1"></label><label>VFD efficiency (%)<input id="altVfd" type="number" value="99" min="50" max="100" step="0.1"></label><label>HVAC COP, same thermal duty<input id="altHvac" type="number" value="3.8" min="2" max="6" step="0.1"></label><label>Cooling COP, same thermal duty<input id="altCooling" type="number" value="5.2" min="2" max="8" step="0.1"></label><label>Fan efficiency, fixed air duty (%)<input id="altFan" type="number" value="75" min="50" max="85"></label><label>Investment (AED)<input id="capex" type="number" value="1500000" min="0"></label><label>Additional annual maintenance (AED)<input id="maintenance" type="number" value="15000" min="0"></label><label>Equivalent days / year<input id="annualDays" type="number" value="365" min="1" max="366"></label><label>Assessment period (years)<input id="years" type="number" value="10" min="1" max="30"></label><label>Discount rate (%)<input id="discount" type="number" value="6" min="0" max="30" step="0.5"></label></div><label class="checkline"><input id="annualConfirm" type="checkbox">I understand that annual results repeat one representative day and are illustrative, without seasonal validation.</label><div class="form-actions"><button class="button primary" data-action="runScenario">Run comparison →</button></div>`)+`<div id="scenarioResults"></div>`;if(S.scenario){let a=S.scenario.changes,f=S.scenario.financial;$('#altStrategy').value=a.strategy;$('#altPump').value=a.pump_factor;$('#altMotor').value=a.motor_eta*100;$('#altVfd').value=a.vfd_eta*100;$('#altHvac').value=a.hvac_cop;$('#altCooling').value=a.cooling_cop;$('#altFan').value=a.fan_efficiency*100;$('#capex').value=f.capex;$('#maintenance').value=f.maintenance;$('#annualDays').value=f.days;$('#years').value=f.years;$('#discount').value=f.discount*100;$('#annualConfirm').checked=f.confirmed;renderScenarioResult()}}
async function runScenario(){await busy(async()=>{let changes={strategy:$('#altStrategy').value,pump_factor:+$('#altPump').value,motor_eta:+$('#altMotor').value/100,vfd_eta:+$('#altVfd').value/100,hvac_cop:+$('#altHvac').value,cooling_cop:+$('#altCooling').value,fan_efficiency:+$('#altFan').value/100};let financial={capex:+$('#capex').value,maintenance:+$('#maintenance').value,days:+$('#annualDays').value,years:+$('#years').value,discount:+$('#discount').value/100,confirmed:$('#annualConfirm').checked};for(let [k,v] of Object.entries(financial)){if(k!=='confirmed'&&(!Number.isFinite(v)||v<0))throw Error('Financial inputs must be finite and non-negative')}if(financial.days<1||financial.days>366||financial.years<1||financial.years>30||financial.years%1||financial.discount>.3)throw Error('Check equivalent days (1–366), years (whole 1–30) and discount (0–30%).');S.scenario={...await api('scenario',{data:S.data,settings:S.config,changes}),changes,financial};renderScenarioResult();$('#scenarioResults').scrollIntoView({behavior:'smooth'})})}
function renderScenarioResult(){let s=S.scenario,el=$('#scenarioResults');if(!el)return;let b=s.baseline,a=s.alternative,f=s.financial,annual=s.daily_cost_difference*f.days-f.maintenance,npv=-f.capex;for(let i=1;i<=f.years;i++)npv+=annual/(1+f.discount)**i;let money=s.comparable&&f.confirmed;el.innerHTML=alert(s.comparable?'Service check passed: hydraulic delivery, terminal storage, auxiliary input ratings and assumed OCU air duty remain within the configured checks.':'Service check failed: review spill, overrides, storage, auxiliary ratings and assumed OCU air duty below. Savings and investment conclusions are withheld.',s.comparable?'neutral':'red')+`<div class="kpis">${kpi('Daily energy difference',F(s.daily_energy_difference),'kWh',F(100*s.daily_energy_difference/b.energy_kwh,2)+'% vs baseline')}${kpi('Daily cost difference',F(s.daily_cost_difference),'AED','Positive = lower modeled cost')}${kpi('Illustrative simple payback',money&&annual>0?F(f.capex/annual,1):'—','years',money?'Includes extra maintenance':'Needs comparable service + annual confirmation')}${kpi('Illustrative NPV',money?F(npv/1000):'—','k AED',f.years+' years · '+F(f.discount*100,1)+'% discount')}</div><div class="grid-even">${panel('Electrical demand comparison','Same inflow, boundary and effective storage',chart('scenarioDemand')+Chart.legend([{name:'Baseline'},{name:'Alternative'}]))}${panel('Storage trajectory','Terminal inventory must be comparable',chart('scenarioLevel')+Chart.legend([{name:'Baseline'},{name:'Alternative'}]))}</div>`+panel('Comparison evidence','Positive energy differences are estimates, not measured savings',table(['Measure','Baseline','Alternative'],[['Energy',F(b.energy_kwh)+' kWh',F(a.energy_kwh)+' kWh'],['Discharged water',F(b.volume_m3)+' m³',F(a.volume_m3)+' m³'],['Modeled spill',F(b.overflow_m3)+' m³',F(a.overflow_m3)+' m³'],['Final wet-well level',F(b.final_level_m,3)+' m',F(a.final_level_m,3)+' m'],['Starts',b.total_starts,a.total_starts],['Low-water overrides',b.emergency_stops,a.emergency_stops],['Auxiliary overload intervals',b.aux_overload_intervals,a.aux_overload_intervals],['OCU below assumed minimum',b.odour_shortfall_intervals,a.odour_shortfall_intervals],['Peak demand',F(b.peak_kw)+' kW',F(a.peak_kw)+' kW']])+`<div class="form-actions"><button class="button" data-action="exportScenario">↓ Export scenario evidence JSON</button></div>`);Chart.line('scenarioDemand',[{name:'Baseline',data:b.rows.map(r=>[r.minute,r.total_kw])},{name:'Alternative',data:a.rows.map(r=>[r.minute,r.total_kw])}],{time:true,unit:'kW'});Chart.line('scenarioLevel',[{name:'Baseline',data:b.rows.map(r=>[r.minute,r.level_end_m])},{name:'Alternative',data:a.rows.map(r=>[r.minute,r.level_end_m])}],{time:true,unit:'m',ymin:0,ymax:b.settings.level_max+.5})}
const DATA_NAMES={inflows:'Inflow profiles',curve:'Single-pump curve',system:'Shared system curves',loads:'Auxiliary load register',zones:'HVAC zone register',weather:'Weather & electricity tariff',meters:'Meter readings'};
function renderData(){let d=S.data;$('#content').innerHTML=head('Data studio','Bring the data. Keep the evidence.','Map columns, normalize units and review quality before a new dataset enters the model.',`<button class="button" data-action="exportWorkspace">↓ Save workspace</button><button class="button ghost" data-action="restoreDemo">Reset demo</button>`)+`<div class="kpis">${kpi('Connected datasets',Object.keys(DATA_NAMES).length,'tables','Separate physical and observation inputs')}${kpi('Inflow coverage',F(d.inflows.filter(r=>r.stage===S.config.stage).reduce((a,r)=>a+ +r.duration_h,0),1),'hours','Selected stage · contiguous profile required')}${kpi('Mapped equipment',d.loads.length,'groups',d.zones.length+' HVAC zones')}${kpi('Data replacements',Object.keys(S.imports).length,'tables','Changes stay in this browser session')}</div>${S.result.aux_overload_intervals||S.result.odour_shortfall_intervals?alert(`Service screening: ${S.result.aux_overload_intervals} intervals exceed an auxiliary input rating; ${S.result.odour_shortfall_intervals} fall below the assumed OCU air duty. Revisit the load register or service assumptions.`,'red'):''}<div class="grid-even">${panel('Connected input tables','Download the active dataset, edit it and bring it back',Object.entries(DATA_NAMES).map(([k,name])=>`<div class="data-file"><span class="file-icon">▤</span><div class="file-desc"><strong>${name}</strong><small>${F(d[k]?.length||0)} rows · ${S.imports[k]?'Imported: '+E(S.imports[k]):k==='curve'?'Approximate reference curve':'Synthetic demonstration'}</small></div><button class="button small" data-download="${k}">CSV ↓</button><button class="button small" data-import="${k}">Replace</button></div>`).join('')+`<p class="scoped-note">Model inputs and meter evidence remain separate. Empty cells, duplicate timestamps, negative flow and overlapping intervals are rejected. Missing time spans are never silently filled.</p>`) }${panel('Import & validate','CSV · UTF-8 · Up to 5 MB · One representative day per stage',`<label class="field">Dataset type<select id="importKind">${Object.entries(DATA_NAMES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><div style="height:15px"></div><div class="dropzone" id="dropzone" tabindex="0" role="button" aria-label="Select a CSV file"><div class="upload-symbol">↑</div><h3>Drop a CSV file here</h3><p>or click to browse your computer</p><input type="file" id="csvFile" accept=".csv,text/csv" hidden></div><div class="actions" style="margin-top:14px"><button class="button small" data-action="exampleImport">Try m³/h mapping example</button><button class="button small" data-action="badImport">Try a quality-check example</button></div><div id="importWork"></div>`)}</div>`+panel('Portable workspace','Export inputs, parameters and provenance together; import your saved JSON to continue',`<div class="actions"><button class="button" data-action="exportWorkspace">Export workspace JSON</button><button class="button" data-action="importWorkspace">Restore workspace JSON</button><input id="workspaceFile" type="file" accept=".json,application/json" hidden></div><p class="scoped-note">A browser refresh restores bundled demonstration data unless you restore a saved workspace. Nothing is uploaded to an external service by this local app.</p>`);
 let dz=$('#dropzone'),file=$('#csvFile');dz.onclick=()=>{file.value='';file.click()};dz.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();file.click()}};file.onchange=()=>{if(file.files[0])readImportFile(file.files[0])};dz.ondragover=e=>{e.preventDefault();dz.classList.add('over')};dz.ondragleave=()=>dz.classList.remove('over');dz.ondrop=e=>{e.preventDefault();dz.classList.remove('over');if(e.dataTransfer.files[0])readImportFile(e.dataTransfer.files[0])};$('#importKind').onchange=()=>{S.importState=null;$('#importWork').innerHTML=''};$('#workspaceFile').onchange=e=>restoreWorkspaceFile(e.target.files[0]);if(S.importState){$('#importKind').value=S.importState.kind;renderImportMap()}
}
function parseHeader(text){let line=text.replace(/^\uFEFF/,'').split(/\r?\n/)[0],out=[],cur='',q=false;for(let i=0;i<line.length;i++){let c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){cur+='"';i++}else q=!q}else if(c===','&&!q){out.push(cur.trim());cur=''}else cur+=c}out.push(cur.trim());return out}
async function readImportFile(file){if(file.size>5e6){toast('CSV limit: 5 MB');return}try{let text=await file.text();S.importState={text,name:file.name,kind:$('#importKind').value,headers:parseHeader(text)};renderImportMap()}catch(e){toast(e.message)}}
function guessColumn(field,headers){let aliases={minute:['time','timestamp','datetime'],duration_h:['hours','interval_h'],inflow_m3s:['flow_m3h','flow_lps','flow','inflow'],q_m3s:['flow_m3h','flow','q'],measured_kw:['power','kw','power_kw'],pump_efficiency:['efficiency','eta'],head_m:['head','tdh'],total_flow_m3s:['flow','total_flow']};return headers.includes(field)?field:(aliases[field]||[]).find(x=>headers.includes(x))||''}
function renderImportMap(){let i=S.importState;if(!i)return;let fields=S.schemas[i.kind];$('#importWork').innerHTML=`<div class="section-title">1 / Map columns</div><p class="subtext">${E(i.name)}</p><div class="mapping">${fields.map(f=>`<label>${E(f)}<select data-map="${f}"><option value="">Select a column…</option>${i.headers.map(h=>`<option ${h===guessColumn(f,i.headers)?'selected':''} value="${E(h)}">${E(h)}</option>`).join('')}</select></label>`).join('')}</div><div class="section-title">2 / Normalize units</div><p class="scoped-note">Conversions apply only to matching flow, electrical-power or pump-efficiency columns.</p><div class="form-grid"><label>Flow unit<select id="flowUnit"><option>m3/s</option><option ${i.headers.some(h=>h.includes('m3h'))?'selected':''}>m3/h</option><option>L/s</option></select></label><label>Power unit<select id="powerUnit"><option>kW</option><option>MW</option></select></label><label>Efficiency unit<select id="etaUnit"><option value="fraction">Fraction (0–1)</option><option value="percent">Percent (0–100)</option></select></label></div><label class="field" style="margin-top:14px">Data provenance<input id="importSource" type="text" value="${E(i.name.startsWith('example')?'Synthetic import example':'User-imported data; source not independently verified')}"></label><p class="scoped-note">Time accepts minute-of-day, HH:MM, or timezone-qualified ISO timestamps. ISO timestamps are converted to UTC; one UTC day per import is supported.</p><div class="form-actions"><button class="button primary" data-action="validateImport">Validate & preview →</button></div><div id="importPreview"></div>`;S.importState.preview=null}
async function validateImport(){await busy(async()=>{let mapping={};$$('[data-map]').forEach(el=>mapping[el.dataset.map]=el.value);if(Object.values(mapping).some(v=>!v))throw Error('Map every required column first.');let i=S.importState,j=await api('import',{kind:i.kind,text:i.text,mapping,units:{flow:$('#flowUnit').value,power:$('#powerUnit').value,efficiency:$('#etaUnit').value},provenance:$('#importSource').value});i.preview=j;$('#importPreview').innerHTML=`<div class="section-title">3 / Quality gate</div>`+alert(j.valid?`${j.raw_count} rows passed structural validation. Check ranges and coverage before applying.`:j.errors.map(E).join('<br>'),j.valid?'neutral':'red')+j.warnings.map(w=>alert(E(w),'')).join('')+Object.entries(j.coverage||{}).map(([k,v])=>`<p class="scoped-note">${E(k)}: ${F(v,2)} hours covered</p>`).join('')+(j.valid?table(['Field','Minimum','Maximum','Mean'],Object.entries(j.stats).map(([k,v])=>[E(k),F(v.min,3),F(v.max,3),F(v.mean,3)])):'')+`<details style="margin-top:14px"><summary style="color:var(--blue);font-size:12px;cursor:pointer">Preview first ${j.preview.length} rows</summary>${table(S.schemas[i.kind],j.preview.map(r=>S.schemas[i.kind].map(k=>E(r[k]))))}</details><div class="form-actions"><button class="button primary" data-action="applyImport" ${j.valid?'':'disabled'}>Apply to workspace</button></div>`})}
async function applyImport(){await busy(async()=>{let i=S.importState;if(!i?.preview?.valid)throw Error('Validate the CSV before applying it.');let data={...S.data,[i.kind]:i.preview.rows};let result=(await api('run',{data,settings:S.config})).result;S.data=data;S.result=result;S.config=result.settings;S.imports[i.kind]=i.name;S.actions.push('Replaced '+DATA_NAMES[i.kind]+' with '+i.name);S.analytics=null;S.scenario=null;S.comparisons=null;S.importState=null;render();updateGlobals();toast('Dataset applied. The model has been recalculated.')})}
function renderReports(){let r=S.result;$('#content').innerHTML=head('Evidence & delivery','Make the demonstration reproducible.','Export the assumptions, calculations and observations that support the story.',`<button class="button" data-action="print">Print current page / PDF →</button>`)+`<div class="export-grid"><button data-action="exportIntervals">Interval results CSV<small>Power, flow, head, storage, cost and pump states.</small></button><button data-action="exportReport">Engineering summary Markdown<small>Current inputs, outcomes, limitations and traceability.</small></button><button data-action="exportResults">Complete calculation JSON<small>Nested per-system, per-zone and per-asset results.</small></button><button data-action="exportWorkspace">Portable workspace JSON<small>Active datasets, settings and import provenance.</small></button><button data-action="exportAnalytics">Deviation evidence CSV<small>Training / test flags, residuals and thresholds.</small></button><button data-action="exportScenario">Scenario evidence JSON<small>Baseline, alternative and financial assumptions.</small></button></div><div style="height:22px"></div><div class="grid-even">${panel('Current assessment','Representative day · '+E(r.settings.stage)+' · '+E(r.settings.head_case)+' head',`<div class="report-block"><p><b>Energy:</b> ${F(r.energy_kwh)} kWh for ${F(r.volume_m3)} m³ delivered (${F(r.sec,3)} kWh/m³).</p><p><b>Hydraulic service:</b> ${F(r.overflow_m3)} m³ modeled spill; final relative water level ${F(r.final_level_m,3)} m.</p><p><b>Cost and carbon:</b> AED ${F(r.cost_aed)} and ${F(r.co2_kg/1000,2)} t CO₂e, using explicit illustrative factors.</p><p><b>Balance:</b> mass residual ${F(r.mass_balance_error_m3,6)} m³. Electrical totals reconcile with the listed systems.</p></div>`)}${panel('Interview walkthrough','A short demonstration with evidence at each step',`<div class="report-block"><ol><li>Orbit the 3D station. Explain the wet well, dry well, pump trains and auxiliary boundaries.</li><li>Open HVAC, then a room, then its equipment load. Explain what is assumed.</li><li>Import the m³/h example, map columns and verify unit conversion.</li><li>Open deviation analytics. Show the held-out anomaly and the residual threshold.</li><li>Run an efficiency comparison. Check water service before showing illustrative savings.</li><li>Export a reproducible evidence package and explain the model's limits.</li></ol></div>`)}</div>`+panel('Evidence register','Source classes are explicit; no live-project measurement is implied',table(['Model element','Evidence class','Implementation'],[['Inflow / weather / tariff','Independent synthetic data','Four development stages; one representative day each'],['Single-pump curve','Approximate manufacturer reference','Duty anchor retained; visual curve shape approximate'],['Auxiliary loads / HVAC zones','Engineering assumptions','Editable CSV registers; not a verified load list'],['Deep-shaft arrangement','Schematic interpretation','Drawing-inspired shafts / decks; six-pump scope selected by user'],['Meter signal','Synthetic injected event or user import','Separated from planning inputs; no verified measurements bundled'],['Spatial model','Original simplified geometry','Orbit, select and inspect; no IFC / BIM import'],['Investment result','Conditional simulation','Same-service check, annual assumptions and no verified savings']]));}
function reportText(){let r=S.result;return `# TPS Twin Studio assessment\n\n## Scope\n${r.settings.stage}; ${r.settings.head_case} head; ${r.settings.boundary}; strategy ${r.settings.strategy}. Representative synthetic day unless replaced via Data studio.\n\n## Results\n- Electrical energy: ${F(r.energy_kwh,3)} kWh\n- Delivered water: ${F(r.volume_m3,3)} m3\n- Station specific energy: ${F(r.sec,6)} kWh/m3\n- Main-pump specific energy: ${F(r.main_sec,6)} kWh/m3\n- Cost: AED ${F(r.cost_aed,2)} (illustrative tariff)\n- Carbon: ${F(r.co2_kg,2)} kg CO2e (assumed factor)\n- Modeled spill: ${F(r.overflow_m3,3)} m3\n- Final level: ${F(r.final_level_m,6)} m relative\n- Mass-balance residual: ${r.mass_balance_error_m3} m3\n- Total starts: ${r.total_starts}; low-water overrides: ${r.emergency_stops}\n\n## System energy (kWh)\n${Object.entries(r.systems).map(([k,v])=>'- '+k+': '+F(v,3)).join('\n')}\n\n## Settings\n\n\`\`\`json\n${JSON.stringify(r.settings,null,2)}\n\`\`\`\n\n## Provenance\n${Object.keys(DATA_NAMES).map(k=>'- '+DATA_NAMES[k]+': '+(S.imports[k]||'Bundled synthetic / approximate reference dataset')).join('\n')}\n\n## Limitations\nApproximate pump curve and assumed operating envelope; no NPSHa or transient verification. Wet-well storage is an effective-area model, not shaft geometry. Scheduling is a heuristic. HVAC room signals are illustrative, not a solved thermal model. Auxiliary loads and tariff are assumptions. No live SCADA, actuation, certified BIM, independently validated faults or verified savings. Repeating a single day does not establish seasonal performance.\n\n## Reproduction\nRestore the exported workspace JSON in Data studio, recalculate, then export results. Source code and tests are included in the project.\n`}
function csvText(rows){if(!rows.length)return '';let keys=Object.keys(rows[0]);const q=x=>{let s=typeof x==='object'?JSON.stringify(x):String(x??'');if(typeof x==='string'&&/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};return keys.map(q).join(',')+'\r\n'+rows.map(r=>keys.map(k=>q(r[k])).join(',')).join('\r\n')}
function download(name,text,type='text/plain'){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Downloaded '+name)}
function saveWorkspace(){download('TPS_workspace.json',JSON.stringify({format:'TPS-Twin-2',data:S.data,settings:S.config,imports:S.imports},null,2),'application/json')}
async function restoreWorkspaceFile(file){if(!file)return;if(file.size>10e6){toast('Workspace JSON limit: 10 MB');return}await busy(async()=>{let j=JSON.parse(await file.text());if(j.format!=='TPS-Twin-2'||!j.data)throw Error('This is not a TPS Twin Studio workspace.');let result=(await api('run',{data:j.data,settings:j.settings})).result;S.data=j.data;S.config=result.settings;S.result=result;S.imports=j.imports||{};S.analytics=null;S.scenario=null;S.comparisons=null;S.importState=null;updateGlobals();render();toast('Workspace restored.')})}
function openModal(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}
function modalHead(title,sub){return `<div class="modal-head"><div><h2>${title}</h2><p class="subtext">${sub}</p></div><button class="icon-btn" data-action="closeModal" aria-label="Close dialog">×</button></div>`}
function showNotes(){openModal(modalHead('A model you can interrogate.','Scope, assumptions and what would be needed for production.')+`<div class="two-col-text"><p><b>Hydraulics.</b> Six identical pump trains share station discharge. Common-pipe friction uses total Q. Affinity scaling finds a feasible common speed; a minimum-input candidate is selected within each interval. Assumed reference limits: 70–94.1% nominal speed, 2.05–3.65 m³/s at reference speed, 3,900 kW shaft power per train.</p><p><b>Storage and scheduling.</b> Inflow − discharge − spill equals change in effective storage. Minimum run/rest durations constrain pump-count changes. Low-level protection can override runtime and is explicitly reported. Tariff-aware control is a heuristic; terminal level recovery occurs in the final hour.</p><p><b>Auxiliaries.</b> Load groups preserve system boundaries. HVAC electricity responds to synthetic outdoor conditions and COP. Central cooling includes an assumed background thermal duty plus 75% of main-motor losses. Cooling and HVAC are separate assumed circuits.</p><p><b>Spatial model.</b> The reference drawing informs the deep-shaft, screen/wet-well, dry-well and deck arrangement. Depth is compressed. External buildings, HVAC zones, locations and areas are illustrative. Six pumps follow the requested scope; the drawing's apparent additional bays are not an as-built inventory.</p><p><b>Analytics.</b> A three-parameter linear model fits the first half of an aligned day, then evaluates the second. Residual alarms are screening rules. The included meter series contains a deliberate synthetic load event.</p><p><b>Production gap.</b> Actual load lists, calibrated meters, validated pump/system curves, NPSHa and transient checks, seasonal weather, control constraints and approved asset geometry are needed. This is a connected planning prototype with no live SCADA or actuation.</p></div>`)}
function showSettings(){let c=S.result.settings;const field=(key,label,help,min,max,step=1,mult=1)=>`<label>${label}${help?tip(help):''}<input data-setting="${key}" data-mult="${mult}" type="number" value="${c[key]*mult}" min="${min}" max="${max}" step="${step}"></label>`;openModal(modalHead('Model inputs','Changes recalculate the hydraulic and energy model together.')+`<div class="section-title">Pump trains & energy factors</div><div class="form-grid">${field('available','Available pumps','Six installed trains; unavailable trains cannot operate.',1,6)}${field('motor_eta','Motor efficiency (%)','Fraction of electrical input converted to shaft output.',50,100,.1,100)}${field('vfd_eta','VFD efficiency (%)','Drive conversion efficiency; not power factor.',50,100,.1,100)}${field('pump_factor','Pump efficiency multiplier','Applied to the approximate reference curve.',.8,1.04,.01)}${field('pf','Power factor','Used for apparent power, not kWh savings.',.5,1,.01)}${field('carbon','Carbon factor (kg CO₂e/kWh)','Illustrative user-entered factor.',0,5,.01)}${field('hvac_cop','HVAC COP','Same assumed thermal service at different electricity input.',2,6,.1)}${field('cooling_cop','Central cooling COP','Thermal duty / chiller electricity.',2,8,.1)}${field('fan_efficiency','Fan efficiency','Same assumed air duty.',.5,.85,.01)}${field('odour_dp_pa','OCU assumed pressure drop (Pa)','Not a measured fan operating point.',500,10000,100)}${field('odour_min_air_m3h','OCU minimum air duty (m³/h)','Illustrative service threshold, not a compliance limit.',1000,1000000,1000)}${field('cooling_delta_k','Cooling-water ΔT (K)','Used to calculate thermal-duty flow.',2,10,.5)}</div><div class="section-title">Wet-well storage & operating rules</div><div class="form-grid">${field('area_m2','Effective wetted area (m²)','Independent assumption, not full shaft area.',100,5000,10)}${field('level_min','Minimum relative level (m)','No absolute project elevation implied.',0,5,.1)}${field('level_max','Maximum relative level (m)','Spill is reported above this bound.',1,10,.1)}${field('level_initial','Initial relative level (m)','Must lie strictly inside the operating band.',0,10,.1)}${field('min_run_min','Minimum run time (min)','Low-water protection overrides are recorded.',0,120,5)}${field('min_off_min','Minimum rest time (min)','Constrains restart eligibility.',0,120,5)}<label>Baseline operating strategy<select data-setting="strategy"><option value="follow">Demand following</option><option value="storage">Storage smoothing</option><option value="tariff">Tariff-aware heuristic</option></select></label><label>Electricity price mode<select data-setting="tariff_mode"><option value="profile">Imported tariff profile</option><option value="flat">Flat illustrative tariff</option></select></label>${field('flat_tariff','Flat tariff (AED/kWh)','Applied only when flat tariff mode is selected.',0,10,.01)}</div><div class="form-actions"><button class="button" data-action="closeModal">Cancel</button><button class="button primary" data-action="saveSettings">Apply & recalculate</button></div>`);$$('select[data-setting]').forEach(el=>el.value=c[el.dataset.setting])}
function showSearch(){let records=[{id:'station',name:'Terminal pumping station',path:'twin',system:'Overview'},...Array.from({length:6},(_,i)=>{let id='P-0'+(i+1);return {id,name:'Main pump '+id,path:'assets/'+id,system:'Main pumping'}}),...S.data.zones.map(z=>({id:z.zone_id,name:z.name,path:'systems/HVAC/'+z.zone_id,system:'HVAC zone'})),...S.data.loads.map(a=>({id:a.asset_id,name:a.name,path:'assets/'+a.asset_id,system:a.system}))];openModal(modalHead('Find an asset','Search equipment IDs, room names and systems.')+'<input id="assetSearch" type="text" placeholder="Try HVAC, motor, CCTV or P-01…" style="width:100%"><div id="searchResults" class="search-results"></div>');let draw=q=>{$('#searchResults').innerHTML=records.filter(r=>(r.id+' '+r.name+' '+r.system).toLowerCase().includes(q.toLowerCase())).map(r=>`<div class="search-row" tabindex="0" role="button" data-search-route="${r.path}"><span class="file-icon">◇</span><div><b>${E(r.name)}</b><small>${E(r.id)} · ${E(r.system)}</small></div><span class="arrow">→</span></div>`).join('')||'<div class="empty">No matching assets</div>'};draw('');$('#assetSearch').oninput=e=>draw(e.target.value);$('#assetSearch').focus()}
function updateGlobals(){$('#globalStage').value=S.config.stage;$('#globalHead').value=S.config.head_case;$('#globalBoundary').value=S.config.boundary;$('#sourceTag').textContent=Object.keys(S.imports).length?'Mixed / imported inputs':'Synthetic planning day';$('#timeline').max=S.result.rows.length-1;S.index=Math.min(S.index,S.result.rows.length-1);$('#timeline').value=S.index;updateTime()}
function updateTime(){if(!S.result)return;let r=current();$('#clock').textContent=T(r.minute);$('#nowPower').textContent=F(r.total_kw)+' kW';$('#nowFlow').textContent=F(r.outflow_m3s,2)+' m³/s';if($('#inspector'))renderInspector();if($('#tankWater')){$('#tankWater').style.height=(100*r.level_end_m/S.result.settings.level_max)+'%';$('#tankLevel').textContent=F(r.level_end_m,2)+' m'}$$('svg[data-timeplot]').forEach(svg=>{let w=svg.viewBox.baseVal.width,l=+svg.dataset.plotLeft,rr=+svg.dataset.plotRight,x=l+r.minute/1440*(w-l-rr),line=svg.querySelector('.time-cursor');if(line){line.setAttribute('x1',x);line.setAttribute('x2',x)}});if(S.twin)S.twin.draw()}
async function recalculate(settings=S.config){return busy(async()=>{let j=await api('run',{data:S.data,settings});S.result=j.result;S.config=j.result.settings;S.analytics=null;S.scenario=null;S.comparisons=null;updateGlobals();render();toast('Model recalculated. Comparisons and analytics were refreshed.')})}
function render(){if(!S.result)return;if(S.twin){S.twin.destroy();S.twin=null}hideTip();let parts=(location.hash.slice(1)||'twin').split('/');S.route=parts[0];$$('.nav-item').forEach(a=>a.classList.toggle('active',a.dataset.page===S.route));let name=NAV.find(n=>n[0]===S.route)?.[2]||'Asset intelligence';$('#breadcrumbs').innerHTML=`<a href="#twin">Workspace</a> <span style="color:#456178"> / </span> ${E(name)}${parts[1]?' / '+E(decodeURIComponent(parts[1])):''}`;if(S.route==='twin')renderTwin();else if(S.route==='performance')renderPerformance();else if(S.route==='systems')renderSystems(parts);else if(S.route==='assets')renderAsset(parts[1]);else if(S.route==='hydraulics')renderHydraulics();else if(S.route==='analytics')renderAnalytics();else if(S.route==='scenarios')renderScenarios();else if(S.route==='data')renderData();else if(S.route==='reports')renderReports();else route('twin');$('.sidebar').classList.remove('open');updateTime()}
async function action(name,el){
 if(name==='closeModal'){$('#modal').close();return}
 if(name==='energyLayer'){S.twin.energy=!S.twin.energy;el.classList.toggle('active',S.twin.energy);S.twin.draw()}
 if(name==='resetView')S.twin?.reset();
 if(name==='tour'){openModal(modalHead('Your six-minute demonstration','An engineering story, supported by inspectable data.')+`<div class="report-block"><ol><li><b>Start in space.</b> Open Cutaway, rotate the station and select a pump train.</li><li><b>Go one level deeper.</b> Select an HVAC building and open its zone analysis.</li><li><b>Show data judgement.</b> Data studio → Try m³/h mapping example → Validate & preview.</li><li><b>Investigate a deviation.</b> Open Deviation analytics; explain the training / test split and residual threshold.</li><li><b>Make a decision.</b> Run an efficiency scenario; verify water service before discussing savings.</li><li><b>Leave evidence.</b> Export the report and workspace so another person can reproduce the result.</li></ol></div>`)}
 if(name==='loadCompare')await loadCompare();if(name==='runScenario')await runScenario();if(name==='validateImport')await validateImport();if(name==='applyImport')await applyImport();
 if(name==='exampleImport'||name==='badImport'){let file=name==='exampleImport'?'import_example_m3h.csv':'import_example_errors.csv',text=await (await fetch('/data/'+file)).text();S.importState={name:'example_'+file,text,kind:'inflows',headers:parseHeader(text)};$('#importKind').value='inflows';renderImportMap()}
 if(name==='showOnTwin'){let id=el.dataset.id;id=({hvac:'Z-ELEC',controls:'Z-CTRL',electrical:'Z-ELEC',buildings:'Z-SERVICE',ventilation:'pumps',aux:'wet'})[id]||id;S.selected=['pumps','wet','cooling','odour','water','station',...S.data.zones.map(z=>z.zone_id),...Array.from({length:6},(_,i)=>'P-0'+(i+1))].includes(id)?id:'station';route('twin')}
 if(name==='exportIntervals'){let rows=S.result.rows.map(r=>Object.fromEntries(Object.entries(r).filter(([k,v])=>typeof v!=='object')));download('TPS_interval_results.csv',csvText(rows),'text/csv')}
 if(name==='exportResults')download('TPS_calculation.json',JSON.stringify(S.result,null,2),'application/json');
 if(name==='exportReport')download('TPS_assessment.md',reportText(),'text/markdown');
 if(name==='exportScenario'){if(!S.scenario){toast('Run a scenario in Scenario lab first.');return}download('TPS_scenario_evidence.json',JSON.stringify(S.scenario,null,2),'application/json')}
 if(name==='exportAnalytics'){if(!S.analytics?.available){toast('Open Deviation analytics and complete the analysis first.');return}download('TPS_residual_evidence.csv',csvText(S.analytics.rows),'text/csv')}
 if(name==='exportWorkspace')saveWorkspace();if(name==='importWorkspace')$('#workspaceFile').click();
 if(name==='restoreDemo'){await busy(async()=>{let data=structuredClone(S.original),j=await api('run',{data,settings:{}});S.data=data;S.result=j.result;S.config=j.result.settings;S.imports={};S.importState=null;S.analytics=null;S.scenario=null;S.comparisons=null;updateGlobals();render();toast('Bundled synthetic demonstration restored.')})}
 if(name==='saveSettings'){let settings={...S.config};$$('[data-setting]').forEach(el=>settings[el.dataset.setting]=el.tagName==='SELECT'?el.value:+el.value/(+el.dataset.mult||1));$('#modal').close();await recalculate(settings)}
 if(name==='print')window.print();
}
document.addEventListener('click',e=>{let r=e.target.closest('[data-route]');if(r)route(r.dataset.route);let a=e.target.closest('[data-action]');if(a)Promise.resolve(action(a.dataset.action,a)).catch(err=>toast(err.message));let v=e.target.closest('[data-view]');if(v){$$('[data-view]').forEach(x=>x.classList.toggle('active',x===v));S.twin.setMode(v.dataset.view)}let imp=e.target.closest('[data-import]');if(imp){$('#importKind').value=imp.dataset.import;S.importState=null;$('#importWork').innerHTML='';$('#dropzone').scrollIntoView({behavior:'smooth',block:'center'});$('#csvFile').click()}let dl=e.target.closest('[data-download]');if(dl)download(dl.dataset.download+'.csv',csvText(S.data[dl.dataset.download]),'text/csv');let sr=e.target.closest('[data-search-route]');if(sr){$('#modal').close();route(sr.dataset.searchRoute)}let pr=e.target.closest('[data-preset]');if(pr){$$('[data-preset]').forEach(x=>x.classList.toggle('active',x===pr));let eff=pr.dataset.preset==='efficiency',c=S.result.settings;$('#altStrategy').value=eff?c.strategy:pr.dataset.preset;$('#altPump').value=eff?1.02:c.pump_factor;$('#altMotor').value=eff?97.5:c.motor_eta*100;$('#altVfd').value=eff?99:c.vfd_eta*100;$('#altHvac').value=eff?3.8:c.hvac_cop;$('#altCooling').value=eff?5.2:c.cooling_cop;$('#altFan').value=eff?75:c.fan_efficiency*100;$('#capex').value=eff?1500000:50000;$('#maintenance').value=eff?15000:3000}});
document.addEventListener('change',e=>{if(e.target.matches('[data-map],#flowUnit,#powerUnit,#etaUnit,#importSource')&&S.importState?.preview){S.importState.preview=null;$('#importPreview').innerHTML=alert('The mapping, units or provenance changed. Validate again before applying.')}});
document.addEventListener('pointerover',e=>{let el=e.target.closest('[data-tip]');if(el)showTip(E(el.dataset.tip),e.clientX,e.clientY)});document.addEventListener('pointerout',e=>{if(e.target.closest('[data-tip]'))hideTip()});document.addEventListener('focusin',e=>{let el=e.target.closest('[data-tip]');if(el){let b=el.getBoundingClientRect();showTip(E(el.dataset.tip),b.x,b.bottom)}});document.addEventListener('focusout',hideTip);
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&S.result){e.preventDefault();if(!$('#modal').open)showSearch()}let r=e.target.closest('[data-search-route]');if(r&&e.key==='Enter'){e.preventDefault();$('#modal').close();route(r.dataset.searchRoute)}});
window.addEventListener('hashchange',()=>{window.scrollTo(0,0);render()});$('#settingsBtn').onclick=()=>S.result&&showSettings();$('#aboutBtn').onclick=showNotes;$('#searchBtn').onclick=()=>S.result&&showSearch();$('#menuBtn').onclick=()=>$('.sidebar').classList.toggle('open');$('#runBtn').onclick=()=>recalculate({...S.config,stage:$('#globalStage').value,head_case:$('#globalHead').value,boundary:$('#globalBoundary').value});$('#timeline').oninput=e=>{S.index=+e.target.value;updateTime()};$('#playBtn').onclick=()=>{S.playing=!S.playing;$('#playBtn').textContent=S.playing?'Ⅱ':'▶';$('#playBtn').setAttribute('aria-label',S.playing?'Pause profile':'Play representative day')};$('#speedBtn').onclick=()=>{S.speed=S.speed===1?3:S.speed===3?6:1;$('#speedBtn').textContent=S.speed+'×'};setInterval(()=>{if(S.playing&&S.result){S.index=(S.index+S.speed)%S.result.rows.length;$('#timeline').value=S.index;updateTime()}},700);
async function boot(){try{let b=await (await fetch('/api/bootstrap')).json();S.token=b.token;S.data=b.data;S.schemas=b.schemas;S.original=structuredClone(b.data);$('#nav').innerHTML=NAV.map(([id,icon,label],i)=>`<a class="nav-item" data-page="${id}" href="#${id}"><b>${navIcon(id)}</b>${label}<span class="nav-n">0${i+1}</span></a>`).join('');let j=await api('run',{data:S.data,settings:S.config});S.result=j.result;S.config=j.result.settings;updateGlobals();render()}catch(e){$('#content').innerHTML=alert('Could not start the model: '+E(e.message)+'. Keep the Python window open and refresh the page.','red');console.error(e)}}
boot();
